"""stages.analysis: generated by the graph.py split (P1)."""

from __future__ import annotations

from .. import prompts
from ..ir import observation
from ..prompts import SYSTEM_PROMPT
from ..runtime import llm_step, parsing, stage_services
from ..runtime.llm import DEFAULT_MAX_TOOL_ROUNDS, OpenAiTextClient
from ..flow import ladder, outcome
from ..stages import fallbacks, feedback as feedback_mod
from ..state import CfuDesignState


def _evidence_paths(state: CfuDesignState) -> list[tuple[str, str]]:
    """Run-relative evidence the analysis stage should read on demand."""
    run_root = str(state.get("run_root", "") or "").rstrip("/")
    if not run_root:
        return []
    return stage_services.existing_evidence(state, [
        (f"{run_root}/02_workload/workload_spec.yaml", "normalized WorkloadSpec"),
        (f"{run_root}/04_benchmark/manifest.yaml", "benchmark workspace and build plan"),
        (f"{run_root}/04_benchmark/embench.yaml", "benchmark workspace and build plan"),
        (f"{run_root}/05_profile/result.yaml", "reference-build cycle profile"),
        (f"{run_root}/05_profile/embench.yaml", "reference-build cycle profile"),
        (f"{run_root}/06_hotspot/hotspot.yaml", "framework hotspot hint (evidence, not a mandate)"),
    ])


def _repair_feedback(state: CfuDesignState) -> str:
    """What the previous analysis attempt got wrong ("" on the first attempt)."""
    gate = (state.get("gates") or {}).get("analysis") or {}
    problems = [str(item) for item in (gate.get("problems") or []) if str(item).strip()]
    if not problems:
        return ""
    return (
        "\n## Previous attempt rejected\n"
        "The previous reply did not contain usable workload-analysis content:\n"
        + "\n".join(f"- {item}" for item in problems)
        + "\nProvide a concise, substantive analysis; YAML is preferred but prose is acceptable.\n"
    )


def analyze_workload(state: CfuDesignState) -> CfuDesignState:
    task = state["task"]
    fallback = {
        "operation": state.get("workload_spec", {}).get("operation", "unknown"),
        "pattern": state.get("workload_spec", {}).get("pattern", "unknown"),
        "hot_spot": state.get("hot_spot", ""),
        "element_type": state.get("workload_spec", {}).get("element_type", ""),
        "unknowns": state.get("workload_spec", {}).get("unknowns", []),
        "roofline": fallbacks.deterministic_roofline_analysis(state.get("workload_spec", {})),
    }
    toolbox = stage_services._toolbox_for_stage(state, "analysis")
    client = llm_step._llm(state)
    tools_enabled = llm_step._tools_enabled(state, client)
    observation_index = None
    if (state.get("benchmark_project") or {}).get("kind") == "embench_benchmark":
        try:
            observation_index = observation.build_observation_index(
                run_root=str(state.get("run_root", "")),
                benchmark=str((state.get("benchmark_project") or {}).get("benchmark", "")),
                observation=state.get("observation_report") or {},
                profiles=state.get("embench_profiles") or {},
                ir_result=state.get("ir_result") or {},
            )
        except ValueError:
            # Evidence lookup is advisory; malformed/unavailable profile data
            # must not turn workload analysis into a new mandatory failure.
            observation_index = None
    ir_views = bool(state.get("llvm_ir", True))
    user = prompts.workload_prompt(
        task,
        state.get("workload_spec", {}),
        state.get("context", {}),
        profile=state.get("embench_profiles"),
        agent_tools=tools_enabled,
        tool_rounds=int(state.get("max_tool_rounds", DEFAULT_MAX_TOOL_ROUNDS) or DEFAULT_MAX_TOOL_ROUNDS),
        ir_evidence=state.get("ir_result"),
        observation_index=observation_index,
        ir_views=ir_views,
        artifact_paths=_evidence_paths(state),
        state=state,
        feedback=_repair_feedback(state) + feedback_mod.upstream_repair_feedback(state),
    )
    result, raw_output, tool_calls = llm_step._run_agent_step(
        state,
        toolbox,
        stage="analyze_workload",
        label="analysis",
        artifact_stage="analysis",
        tool_calls_relpath="07_analysis/analysis_tool_calls.yaml",
        system=SYSTEM_PROMPT,
        user=user,
        fallback=parsing._yaml_str(fallback),
        client=client,
        deliverable_hint="concise workload analysis; YAML mapping preferred, prose is acceptable",
        observation_index=observation_index,
        toolset_kwargs={"ir_views": ir_views},
    )
    raw_analysis = (result.text or "").strip()
    parsed = parsing.parse_yaml_mapping(result.text)
    if isinstance(client, OpenAiTextClient) and not result.used_llm and not state.get("dry_run", False):
        raise RuntimeError("workload analysis requires a model-authored response")
    if state.get("dry_run", False) and parsed is None:
        analysis = fallback
    elif parsed:
        analysis = parsed
    elif raw_analysis:
        # The analysis is advisory context, not a generator input schema. Keep
        # useful prose or malformed-YAML content rather than blocking the design
        # ladder on serialization; the persisted artifact is still valid YAML.
        analysis = {"summary": raw_analysis}
    else:
        analysis = {}
    if analysis and not isinstance(analysis.get("roofline"), dict):
        analysis["roofline"] = fallback["roofline"]
    analysis_errors = [] if analysis or state.get("dry_run", False) else [
        "analysis response was empty; no workload-analysis content can be passed downstream"
    ]
    if analysis_errors:
        analysis_errors.append("the model must provide substantive workload-analysis content")
    ir = state.get("ir_result") or {}
    if ir.get("mode") in {"auto", "require", "approx"}:
        # Preserve evidence provenance even if the LLM omits it; P0 does not
        # synthesize static loop features or treat IR as measured cycles.
        analysis["ir_evidence"] = {
            "status": ir.get("status", "unavailable"),
            "reason": ir.get("reason", ""),
            "target_match": ir.get("toolchain", {}).get("target_match", False),
            "ir_files": ir.get("ir_files", []),
            "feature_files": ir.get("feature_files", []),
            "feature_extraction": ir.get("feature_extraction", {}),
            "provenance": "07_analysis/ir_features.yaml",
        }
    note = "Analyzed workload with LLM." if result.used_llm else "Analysis is only a dry-run planning hint."
    stage_services._write_analysis_artifact(state, analysis)
    ok = not analysis_errors
    # A shape error is an answer error, not a design error: repair it from the
    # small answer pool, and stop the run when it cannot be produced. Without
    # this the empty mapping silently became the input of every later stage
    # (observed 2026-09-29: ``Workload analysis: {}`` reached the ISA prompt).
    extra, next_node = ladder._ladder_transition(
        state,
        "analysis",
        ok=ok,
        default="design_contract",
        repair_target="analyze_workload",
    )
    update = {
        "workload_analysis": parsing._yaml_str(analysis),
        "llm_raw_outputs": [raw_output],
        "tool_calls": [llm_step._tool_call_summary(call) for call in tool_calls],
        "stage_jobs": next_node,
        "errors": analysis_errors,
        **outcome.stage_result(state, rung="analysis", ok=ok,
                               problems=analysis_errors, next=next_node,
                               planned=bool(state.get("dry_run", False)),
                               history=note),
    }
    return ladder._apply_transition(update, extra)
